\title{Deep-Unfolded Wideband ISAC Beamforming for DMA Under Frequency-Selective Lorentzian Model}
\author{Abdolrasoul Sakhaei Gharagezlou, {\it Graduate Student Member, IEEE}, Pouya Mobaraki, {\it Graduate Student Member, IEEE},
Mehdi Monemi, {\it Member, IEEE}, Nhan Thanh Nguyen, {\it Senior Member, IEEE},
