In this paper, we assume that B has imperfect CSI estimates about
$\mathbf{h}_{\mathrm{B},i}$, $\mathbf{h}_{\mathrm S,i}$, $\mathbf{g}_{\mathrm{B},e}$,
$\mathbf{g}_{\mathrm S,e}$, and $\mathbf{V}_{l}$,
respectively denoted by $\widehat{\mathbf{h}}_{\mathrm{B},i}$, $\widehat{\mathbf{h}}_{\mathrm S,i}$,
$\widehat{\mathbf{g}}_{\mathrm{B},e}$, $\widehat{\mathbf{g}}_{\mathrm S,e}$, and $\widehat{\mathbf{V}}_{l}$,
with the corresponding CSI errors denoted by $\bm{\delta}_{\mathrm{B},i}\sim\mathcal{CN}(\bm{0},\varsigma_{\mathrm{B},i}^{2}\mathbf{I})$,
$\bm{\delta}_{\mathrm S,i}\sim\mathcal{CN}(\bm{0},\varsigma_{\mathrm S,i}^{2}\mathbf{I})$,
$\bm{\delta}_{\mathrm{B},e}\sim\mathcal{CN}(\bm{0},\varsigma_{\mathrm{B},e}^{2}\mathbf{I})$,
$\bm{\delta}_{\mathrm S,e}\sim\mathcal{CN}(\bm{0},\varsigma_{\mathrm S,e}^{2}\mathbf{I})$,
and $\bm{\Delta}_{l}\sim\mathcal{CN}(\bm{0},\varsigma_{l}^{2}\mathbf{I})$.
WLOG, in the rest of this paper, we assume that $\varsigma_{\mathrm{B},i}^{2}=\varsigma_{\mathrm S,i}^{2}=\varsigma_{\mathrm{B},e}^{2}=\varsigma_{\mathrm S,e}^{2}=\varsigma_{l}^{2}=\varsigma^{2},\forall i\in\mathcal{I},e\in\mathcal{E},l\in\mathcal{L}$. 
\subsection{Communication Model at the IRs}
The received signal at the $i$-th IR is given by 
\begin{align}
y_{\mathrm{I},i}=\  & \big(\mathbf{h}_{\mathrm{B},i}+\mathbf{h}_{\mathrm S,i}\bm{\Theta}_{\mathrm{I},i}\mathbf{H}\big)\mathbf{x}+n_{\mathrm{I},i}\nonumber 
=\  & \big(\underbrace{\widehat{\mathbf{h}}_{\mathrm{B},i}+\widehat{\mathbf{h}}_{\mathrm S,i}\bm{\Theta}_{\mathrm{I},i}\mathbf{H}}_{\triangleq\widehat{\mathbf{z}}_{\mathrm{I},i}}\big)\mathbf{x}+\big(\underbrace{\bm{\delta}_{\mathrm{B},i}+\bm{\delta}_{\mathrm S,i}\bm{\Theta}_{\mathrm{I},i}\mathbf{H}}_{\triangleq\bm{\delta}_{\mathrm{I},i}}\big)\mathbf{x}+n_{\mathrm{I},i}\nonumber 
=\  & \widehat{\mathbf{z}}_{\mathrm{I},i}\mathbf{x}+\bm{\delta}_{\mathrm{I},i}\mathbf{x}+n_{\mathrm{I},i},\label{eq:rx-signal_Ii}
\end{align}
where $n_{\mathrm{I},i}\sim\mathcal{CN}(0,\sigma_{\mathrm{I},i}^{2})$
is the additive white Gaussian noise (AWGN) at the $i$-th IR. Moreover, $\bm{\Theta}_{\mathrm{I},i}=\diag(\bm{\theta}_{\mathrm{I},i})$
with $\bm{\theta}_{\mathrm{I},i}$ being the STAR-RIS response
for the $i$-th IR. In this paper, we consider the power-splitting
protocol at the STAR-RIS, \emph{i.e.}, for an incident signal $x$, the response
of the $\varkappa$-th STAR-RIS meta-atom $\big(\varkappa\in\mathcal{M}_{\mathrm S}\triangleq\{1,2,\ldots,M_{\mathrm S}\}\big)$ in the reflection and transmission
regions are respectively given by $\theta_{\mathsf{R},\varkappa}$
and $\theta_{\mathsf{T},\varkappa}$, provided $\angle\theta_{\mathsf{R},\varkappa},\angle\theta_{\mathsf{T},\varkappa}\in[0,2\pi)$
and $\sum_{\mathsf{m}\in\{\mathsf{R},\mathsf{T}\}}|\theta_{\mathsf{m},\varkappa}|^{2}=1$.
Therefore, we can define $\bm{\theta}_{\mathrm{I},i}$ as 
\begin{align}
\bm{\theta}_{\mathrm{I},i}=\mathbb{A}_{\mathrm{I},i}\bm{\theta}_{\mathsf{R}}+(1-\mathbb{A}_{\mathrm{I},i})\bm{\theta}_{\mathsf{T}},\label{eq:theta_Ii_def}
\end{align}
where the indicator function $\mathbb{A}_{\mathrm{I},i}=1$ if the
$i$-th IR lies in the reflection region of the STAR-RIS, and $\mathbb{A}_{\mathrm{I},i}=0$
otherwise. Here $\bm{\theta}_{\mathsf{R}}=[\theta_{\mathsf{R},1},\ldots,\theta_{\mathsf{R},M_{\mathrm S}}]\trans\in\mathbb{C}^{M_{\mathrm S}\times1}$,
and $\bm{\theta}_{\mathsf{T}}=[\theta_{\mathsf{T},1},\ldots,\theta_{\mathsf{T},M_{\mathrm S}}]\trans\in\mathbb{C}^{M_{\mathrm S}\times1}$.
We denote $\mathbf{F}=[\mathbf{f}_{\mathrm{I},1},\ldots,\mathbf{f}_{\mathrm{I},I},\mathbf{f}_{\mathrm{E},1},\ldots,\mathbf{f}_{\mathrm{E},E},\mathbf{f}_{\mathrm{T},1},\ldots,\mathbf{f}_{\mathrm{T},L}]\in\mathbb{C}^{M_{\mathrm{T}}\times(I+E+L)}$
as the stack of all transmit beamforming vectors and $\bm{\theta}=\big[\bm{\theta}_{\mathsf{R}}\trans,\bm{\theta}_{\mathsf{T}}\trans\big]\trans\in\mathbb{C}^{2M_{\mathrm S}\times1}$
as the STAR-RIS beamforming vector. With a slight abuse of notations,
we redefine the stack of transmit beamforming vectors as $\mathbf{F}\triangleq\big[\mathbf{f}_{1},\ldots,\mathbf{f}_{I},\mathbf{f}_{I+1},\ldots\mathbf{f}_{I+E},\mathbf{f}_{I+E+1},\ldots\mathbf{f}_{I+E+L}\big]$.
We assume that the $i$-th IR is interested only in decoding $w_{\mathrm I,i}$, and hence, the SINR for decoding the intended signal $w_{\mathrm{I},i}$ at the
$i$-th IR can be given by
\begin{align}
&\gamma_{\mathrm{I},i}(\mathbf{F},\bm{\theta})= \frac{\big|\widehat{\mathbf{z}}_{\mathrm{I},i}\mathbf{f}_{i}\big|^{2}}{\underbrace{\sum\limits_{\jmath\in\mathcal{Q}\setminus \{i\}}\big|\widehat{\mathbf{z}}_{\mathrm{I},i}\mathbf{f}_{\jmath}\big|^{2}}_{\text{MUI}}+\underbrace{\sum\limits_{q\in\mathcal{Q}}\mathbb{E}\big\{\big|\bm{\delta}_{\mathrm{I},i}\mathbf{f}_{q}\big|^{2}\big\}}_{\text{ICE}}+\sigma_{\mathrm{I},i}^{2}}\nonumber 
&\!= \!\frac{\big|\widehat{\mathbf{z}}_{\mathrm{I},i}\mathbf{f}_{i}\big|^{2}}{\sum\limits_{\jmath\in\mathcal{Q} \setminus \{i\}} \! \big|\widehat{\mathbf{z}}_{\mathrm{I},i}\mathbf{f}_{\jmath}\big|^{2} \!+\!\varsigma^{2}\!\sum\limits_{q\in\mathcal{Q}}\!\Big(\big\Vert\mathbf{f}_{q}\big\Vert^{2}\!+\!\big\Vert\bm{\Theta}_{\mathrm{I},i}\mathbf{H}\mathbf{f}_{q}\big\Vert^{2}\Big)\!+\!\sigma_{\mathrm{I},i}^{2}},
 \label{eq:gamma_Ii}
\end{align}
where $\mathcal{Q}\triangleq\{1,2,\ldots,Q\}$, $Q = I+E+L$ and ICE represents the interference due to CSI errors. 
\subsection{Power Harvesting Model at the ERs}
At the same time, the signal received at the $e$-th ER is given by
\begin{align}
&y_{\mathrm{E},e}=\big(\mathbf{g}_{\mathrm{B},e}+\mathbf{g}_{\mathrm S,e}\bm{\Theta}_{\mathrm{E},e}\mathbf{H}\big)\mathbf{x}+n_{\mathrm{E},e}\nonumber 
&= \big(\underbrace{\widehat{\mathbf{g}}_{\mathrm{B},e}+\widehat{\mathbf{g}}_{\mathrm S,e}\bm{\Theta}_{\mathrm{E},e}\mathbf{H}}_{\triangleq\widehat{\mathbf{z}}_{\mathrm{E},e}}\big)\mathbf{x}+\big(\underbrace{\bm{\delta}_{\mathrm{B},e}+\bm{\delta}_{\mathrm S,e}\bm{\Theta}_{\mathrm{E},e}\mathbf{H}}_{\triangleq\bm{\delta}_{\mathrm{E},e}}\big)\mathbf{x}+n_{\mathrm{E},e}\nonumber 
&= \widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{x}+\bm{\delta}_{\mathrm{E},e}\mathbf{x}+n_{\mathrm{E},e},\label{eq:rx_signal_Ee}
\end{align}
where $n_{\mathrm{E},e}\sim\mathcal{CN}(0,\sigma_{\mathrm{E},e}^{2})$
is the AWGN at the $e$-th ER. Moreover, $\bm{\Theta}_{\mathrm{E},e}=\diag(\bm{\theta}_{\mathrm{E},e})$,
and 
\begin{align}
\bm{\theta}_{\mathrm{E},e}=\mathbb{A}_{\mathrm{E},e}\bm{\theta}_{\mathsf{R}}+(1-\mathbb{A}_{\mathrm{E},e})\bm{\theta}_{\mathsf{T}},\label{eq:theta_Ee_def}
\end{align}
where the indicator function $\mathbb{A}_{\mathrm{E},e}=1$ if the
$e$-th ER lies in the reflection region of the STAR-RIS, and $\mathbb{A}_{\mathrm{E},e}=0$
otherwise. Hence the total harvested power at the $e$-th ER is given
by
\begin{align}
 & P_{\mathrm{E},e}(\mathbf{F},\bm{\theta})=\eta_{\mathrm{E},e}\sum\limits_{q\in\mathcal{Q}}\Big(|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{q}|^{2}+\mathbb{E}\big\{|\bm{\delta}_{\mathrm{E},e}\mathbf{f}_{q}|^{2}\big\}\Big)\nonumber 
&=\ \eta_{\mathrm{E},e}\sum\limits_{q\in\mathcal{Q}}\Big(|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{q}|^{2}+\varsigma^{2} \Big\{\big\Vert\mathbf{f}_{q}\big\Vert^{2}+\big\Vert\bm{\Theta}_{\mathrm{E},e}\mathbf{H}\mathbf{f}_{q}\big\Vert^{2}\Big\}\Big),\label{eq:harvested_power_Ee}
\end{align}
where $0<\eta_{\mathrm{E},e}<1$ is the power harvesting efficiency
of the $e$-th ER, and WLOG, it is assumed that the noise power at the ERs is negligibly small with respect to (w.r.t.) the power harvested at the ERs. 
\subsection{Information Leakage Model at the ERs}
In this paper, we assume that ERs are potential eavesdroppers, and each of the ERs attempts to decode the information symbols, $w_{\mathrm I, i}$. The SINR at the $e$-th ER to decode the signal intended for the $i$-th
IR, \emph{i.e.}, $w_{\mathrm{I},i}$ is given by 
\begin{align}
&\gamma_{\mathrm{E},e,i}(\mathbf{F},\bm{\theta})=  \frac{\big|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{i}\big|^{2}}{\underbrace{\sum\limits_{\jmath\in\mathcal{Q}\setminus \{i\}}|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{\jmath}|^{2}}_{\text{MUI}}+\underbrace{\sum\limits_{q\in\mathcal{Q}}\mathbb{E}\big\{\big|\bm{\delta}_{\mathrm{E},e}\mathbf{f}_{q}\big|^{2}\big\}}_{\text{ICE}}+\sigma_{\mathrm{E},e}^{2}}\nonumber 
&\!=\!\frac{\big|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{i}\big|^{2}}{\sum\limits_{\jmath\in\mathcal{Q} \setminus \{i\}}\!\!\big|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{\jmath}\big|^{2}\!+\!\varsigma^{2}\!\!\sum\limits_{q\in\mathcal{Q}}\!\!\Big(\big\Vert\mathbf{f}_{q}\big\Vert^{2}\!+\!\big\Vert\bm{\Theta}_{\mathrm{E},e} \mathbf{H}\mathbf{f}_{q}\big\Vert^{2}\Big)\!+\!\sigma_{\mathrm{E},e}^{2}}.
 \label{eq:gamma_Ee}
\end{align}
\subsection{Sensing Model at the DFBS}
We now model the sensing performance metric in terms of the received echo SINR at B. For this purpose, the received echo signal from the $l$-th target at B can be given by 
\begin{align}
\mathbf{y}_{\mathrm{B}}=\  & \sum\nolimits_{l\in\mathcal{L}}\alpha_{l}\mathbf{V}_{l}\mathbf{x}+\mathbf{G}\mathbf{x}+\mathbf{n}_{\mathrm{B}}\nonumber 
=\  & \sum\nolimits_{l\in\mathcal{L}}\alpha_{l}\left(\widehat{\mathbf{V}}_{l} + \bm{\Delta}_{l} \right) \mathbf{x}+\mathbf{G}\mathbf{x}+\mathbf{n}_{\mathrm{B}},\label{eq:yB}
\end{align}
where $\alpha_{l}$ is the radar cross-section (RCS) of the $l$-th target with $\mathbb{E}\{|\alpha_{l}|^{2}\}=\bar{\alpha},\forall l\in\mathcal{L}$ and $\mathbf{n}_{\mathrm{B}}\sim\mathcal{CN}(\mathbf{0},\sigma_{\mathrm{B}}^{2}\mathbf{I})$ is the AWGN vector at the receive antenna array at B. 
Before processing the received signal, B applies a receive beamforming vector $\mathbf{c}_{l}\in\mathbb{C}^{M_{\mathrm{R}}\times1}$ to sense the $l$-th target, resulting in the following post-combining echo SINR for the $l$-th target:
\begin{align}
 & \gamma_{\mathrm{B},l}(\mathbf{F},\mathbf{c}_{l})=\bar{\alpha}\sum\limits_{q\in\mathcal{Q}}\big|\mathbf{c}_{l}^{\mathsf{H}}\widehat{\mathbf{V}}_{l}\mathbf{f}_{q}\big|^{2}\Big[\bar{\alpha}\sum\limits_{\jmath\in\mathcal{L} \setminus \{l\}}\sum\limits_{q\in\mathcal{Q}}\big|\mathbf{c}_{l}^{\mathsf{H}}\widehat{\mathbf{V}}_{\jmath}\mathbf{f}_{q}\big|^{2}\nonumber 
&+\sum\limits_{q\in\mathcal{Q}}\Big(\bar{\alpha}\varsigma^{2}\big\Vert\mathbf{c}_{l}\big\Vert^{2}\big\Vert\mathbf{f}_{q}\big\Vert^{2}+\big|\mathbf{c}_{l}^{\mathsf{H}}\mathbf{G}\mathbf{f}_{q}\big|^{2}\Big)+\sigma_{\mathrm{B}}^{2}\big\Vert\mathbf{c}_{l}\big\Vert^{2}\Big]^{-1}.\label{eq:gamma_Bl}
\end{align}
We further define the stack of receive beamforming vectors as $\mathbf{C}\triangleq[\mathbf{c_{1}},\ldots,\mathbf{c}_{L}]\in\mathbb{C}^{M_{\mathrm{R}}\times L}$. 
\subsection{Problem Formulation}
With the given background, we now formulate the following optimization problem:\footnote{We assume that the targets are passive nodes without transceiver capability, and hence do not pose any security threat to the network. Likewise, the IRs are considered trusted users. These assumptions simplify the formulated problem, while the more general case with eavesdropping targets and untrusted users is left for future research.} 
\begin{subequations}
\label{eq:P1}
\begin{align}
\underset{\mathbf{F},\bm{\theta},\mathbf{C}}{\min}\  & \|\mathbf{F}\|_{\mathsf{F}}^{2} \label{eq:P1-objective}
\text{s.t.}\  & \gamma_{\mathrm{I},i}(\mathbf{F},\bm{\theta})\geq\Gamma_{\mathrm{I},i},\forall i\in\mathcal{I},\label{eq:P1-comm}
 & P_{\mathrm{E},e}(\mathbf{F},\bm{\theta})\geq\mathcal{P}_{e},\forall e\in\mathcal{E},\label{eq:P1-EH}
 & \gamma_{\mathrm{E},e,i}(\mathbf{F},\bm{\theta})\leq\Gamma_{\mathrm{E},e,i},\forall e\in\mathcal{E},i\in\mathcal{I},\label{eq:P1-leakage}
 & \gamma_{\mathrm{B},l}(\mathbf{F},\mathbf{c}_{l})\geq\Gamma_{\mathrm{B},l},\forall l\in\mathcal{L},\label{eq:P1-sensing}
 & \|\mathbf{c}_{l}\|^{2}=1,\forall l\in\mathcal{L},\label{eq:P1-unit-norm-beamforming}
 & \sum\nolimits_{\mathsf{m}\in\{\mathsf{R},\mathsf{T}\}}|\theta_{\mathsf{m},\varkappa}|^{2}=1,\forall\varkappa\in\mathcal{M}_{\mathrm S}.\label{eq:P1-UMC}
\end{align}
\end{subequations}
In~\eqref{eq:P1}, we aim to minimize the total transmit power from B, while maintaining a given communication QoS constraint for every IR, a power harvesting QoS constraint for every ER, an information leakage
QoS constraint at every ER corresponding to every information symbol, a sensing QoS constraint corresponding to every target, and the power-splitting protocol at the STAR-RIS. More specifically,~\eqref{eq:P1-objective} is the total transmit power from B, \eqref{eq:P1-comm} ensures that the SINR at the $i$-th IR is greater than or equal to the predefined threshold $\Gamma_{\mathrm{I},i}$, \eqref{eq:P1-EH} enforces that the total harvested power at the $e$-th ER is greater than or equal to $\mathcal{P}_{e}$, \eqref{eq:P1-leakage} ensures that the SINR of decoding $w_{\mathrm{I},i}$ (\emph{i.e.}, symbol intended for the $i$-th IR) at the $e$-th ER (\emph{i.e.}, the information leakage) is less than or equal to $\Gamma_{\mathrm{E},e,i}$, \eqref{eq:P1-sensing} ensures that the sensing SINR corresponding to the $l$-th target at B is at least $\Gamma_{\mathrm{B},l}$, \eqref{eq:P1-unit-norm-beamforming} enforces that echo signals are not amplified at the receive antenna array of B, and~\eqref{eq:P1-UMC} is due to the power-splitting protocol at the STAR-RIS.\footnote{Although a more practical coupled transmission–reflection phase-shift model for STAR-RIS was proposed in~\cite{22-JSTSP-STAR}, this work adopts the widely used decoupled phase-shift model to ensure analytical tractability.} 
In the following section, we propose an AO-based numerically efficient solution to~\eqref{eq:P1}, and present the corresponding convergence and complexity analyses of the proposed algorithm.
\section{AO-Based Proposed Solution}
The optimization problem in~\eqref{eq:P1} is a nonconvex quadratically constrained quadratic program (QCQP). Its nonconvexity arises entirely from the constraints: the QoS constraints in~\eqref{eq:P1-comm}–\eqref{eq:P1-leakage} involve SINR and harvested-power expressions that are quadratic functions jointly w.r.t. the transmit beamforming matrix $\mathbf{F}$ and the STAR-RIS coefficients $\bm{\theta}$, while the sensing QoS constraints in~\eqref{eq:P1-sensing} contain bilinear couplings between $\mathbf{F}$ and the receive combiners $\mathbf{c}_{l}$. In addition, the unit-norm and power-splitting equalities in~\eqref{eq:P1-unit-norm-beamforming} and~\eqref{eq:P1-UMC} are also nonconvex quadratic constraints, so that the feasible set is nonconvex and standard convex optimization techniques cannot be applied directly.
To solve this challenging non-convex optimization
problem, we propose an AO-based iterative approach, where the optimal
receive beamforming vectors ($\mathbf{C}$) are obtained in closed-form
via eigenvalue decomposition, and then we simultaneously optimize
$\mathbf{F}$ and $\bm{\theta}$ using a sequence of convex
approximations.\footnote{It is worth emphasizing that the SCA framework developed in this work could, in principle, be extended to jointly update the entire variable tuple $(\mathbf{F},\bm{\theta},\mathbf{C})$ within a single convex surrogate problem at each iteration. However, we intentionally adopt a block coordinate / AO strategy, in which $(\mathbf{F},\bm{\theta})$ are updated via SCA whereas $\mathbf{C}$ is computed in closed-form, to exploit the problem structure, maintain manageable per-iteration computational complexity, and avoid solving an unnecessarily high-dimensional convex program.}
\subsection{Optimal Receive Beamforming for Fixed \texorpdfstring{$(\mathbf{F},\bm{\theta})$}{ (F, theta)}}
Observe that the receive beamforming vectors enter the formulation only through~\eqref{eq:P1-sensing} and~\eqref{eq:P1-unit-norm-beamforming}. Using~\eqref{eq:gamma_Bl}, the post-combining sensing SINR can be written as
\begin{align}
\gamma_{\mathrm{B},l}(\mathbf{c}_{l})=\frac{\mathbf{c}_{l}^{\mathsf{H}}\mathbf{M}_{1,l}\mathbf{c}_{l}}{\mathbf{c}_{l}^{\mathsf{H}}\mathbf{M}_{2,l}\mathbf{c}_{l}},\label{eq:gamma_Bl_transform}
\end{align}
where 
\begin{align}
\mathbf{M}_{1,l}\triangleq\bar{\alpha}\sum\nolimits_{q\in\mathcal{Q}}\widehat{\mathbf{V}}_{l}\mathbf{f}_{q}\mathbf{f}_{q}^{\mathsf{H}}\widehat{\mathbf{V}}_{l}^{\mathsf{H}},\label{eq:M1l}
\end{align}
and 
\begin{multline}
\mathbf{M}_{2,l}\triangleq  \bar{\alpha}\sum\nolimits_{\jmath\in\mathcal{L} \setminus \{l\}}\sum\nolimits_{q\in\mathcal{Q}}\widehat{\mathbf{V}}_{\jmath}\mathbf{f}_{q}\mathbf{f}_{q}^{\mathsf{H}}\widehat{\mathbf{V}}_{\jmath}^{\mathsf{H}} 
 +\bar{\alpha}\varsigma^{2}\big\Vert\mathbf{F}\big\Vert_{\mathsf{F}}^2\mathbf{I} +\sum\nolimits_{q\in\mathcal{Q}}\mathbf{G}\mathbf{f}_{q}\mathbf{f}_{q}^{\mathsf{H}}\mathbf{G}^{\mathsf{H}}+\sigma_{\mathrm{B}}^{2}\mathbf{I}.\label{eq:M2l}
\end{multline}
In~\eqref{eq:gamma_Bl_transform}, we suppress the explicit dependence of the sensing SINR on $\mathbf{F}$ on the left-hand side (LHS), since the transmit beamforming vectors are treated as fixed parameters while optimizing over $\mathbf{c}_{l}$. For fixed $(\mathbf{F},\bm{\theta})$, maximizing $\gamma_{\mathrm{B},l}(\mathbf{c}_{l})$ subject to the unit-norm constraint in~\eqref{eq:P1-unit-norm-beamforming} constitutes a fractional quadratic program over the complex unit sphere. Since $\mathbf{M}_{1,l}$ and $\mathbf{M}_{2,l}$ are Hermitian and $\mathbf{M}_{2,l}\succ\mathbf{0}$ (due to the noise and interference terms), this subproblem can be equivalently expressed as a \emph{generalized Rayleigh quotient maximization} and admits a \emph{closed-form global solution} given by the principal generalized eigenvector of the matrix pair $(\mathbf{M}_{1,l},\mathbf{M}_{2,l})$. Equivalently, the optimal receive combiner at the $\upsilon$-th iteration can be given by
\begin{align}
\mathbf{c}_{l}^{(\upsilon)}=\bm{\lambda}_{\max}\big(\mathbf{M}_{2,l}^{-1}\mathbf{M}_{1,l}\big),\label{eq:cl_opt}
\end{align}
where $\bm{\lambda}_{\max}(\mathbf{X})$ denotes the generalized principal eigenvector of the matrix $\mathbf{X}$. By convention, the eigenvectors are taken to have unit Euclidean norm, so~\eqref{eq:cl_opt} satisfies the constraint in~\eqref{eq:P1-unit-norm-beamforming} by construction.
\subsection{Optimal \texorpdfstring{$(\mathbf{F},\bm{\theta})$}{ (F, theta)} for Fixed \texorpdfstring{$\mathbf{C}$}{ C}}
In this subsection, we use a sequence of convex approximation to simultaneously update $\mathbf{F}$ and $\bm{\theta}$, while $\mathbf{C}$ is fixed. Note that for a given $\mathbf{C}$,~\eqref{eq:P1} can be reformulated as follows: 
\begin{align}
\underset{\mathbf{F},\bm{\theta}}{\min}\ \big\{\|\mathbf{F}\|_{\mathsf{F}}^{2}\mid\eqref{eq:P1-comm}-\eqref{eq:P1-sensing},\eqref{eq:P1-UMC}\big\}.
\label{eq:P2}
\end{align}
It is easy to note that the objective in~\eqref{eq:P2} is already convex, and due to the minimization problem, no transformation is required. We thus shift our focus to convexify the constraints in~\eqref{eq:P1-comm}. 
\begin{theorem}
\label{thm:comm-Convex}For a fixed $i\in\mathcal{I}$, a convex equivalent
of~\eqref{eq:P1-comm} is given by 
\begin{subequations}
\label{eq:P1-comm-CONVEX}
\begin{align}
 & \frac{1}{\Gamma_{\mathrm{I},i}}\psi_{\mathrm{I},i}\big(\mathbf{f}_{i},\bm{\theta};\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big)\geq\sum\nolimits_{\jmath\in\mathcal{Q} \setminus \{i\}}\big(\tau_{\mathrm{I},\jmath}^{2}+\bar{\tau}_{\mathrm{I},\jmath}^{2}\big) +\varsigma^{2}\nonumber 
 & \times \sum_{q\in\mathcal{Q}}\Big[\big\Vert\mathbf{f}_{q}\big\Vert^{2}+\sum\limits_{\varkappa\in\mathcal{M}_{\mathrm S}}\big(\varphi_{\mathrm{I},i,q,\varkappa}^{2}+\bar{\varphi}_{\mathrm{I},i,q,\varkappa}^{2}\big)\Big]+\sigma_{\mathrm{I},i}^{2},\label{eq:P1-comm-A}
 & \tau_{\mathrm{I},i,\jmath}\geq\zeta_{\mathrm{I},i,\jmath}\big(\mathbf{f}_{\jmath},\bm{\theta};\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),\forall\jmath\in\mathcal{Q}\setminus \{i\}, \label{eq:P1-comm-B}
 &\tau_{\mathrm{I},i,\jmath}\geq\zeta_{\mathrm{I},i,\jmath}\big(-\mathbf{f}_{\jmath},\bm{\theta};-\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),\forall\jmath\in\mathcal{Q}\setminus \{i\}, \label{eq:P1-comm-C}
 & \bar{\tau}_{\mathrm{I},i,\jmath}\geq\bar{\zeta}_{\mathrm{I},i,\jmath}\big( j\mathbf{f}_{\jmath},\bm{\theta}; j\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),\forall\jmath\in\mathcal{Q}\setminus \{i\},\label{eq:P1-comm-D}
 & \bar{\tau}_{\mathrm{I},i,\jmath}\geq\bar{\zeta}_{\mathrm{I},i,\jmath}\big(- j\mathbf{f}_{\jmath},\bm{\theta};- j\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),\forall\jmath\in\mathcal{Q}\setminus \{i\},\label{eq:P1-comm-E}
 & \varphi_{\mathrm{I},i,q,\varkappa}\geq\mu_{\mathrm{I},i,q,\varkappa}\big(\mathbf{f}_{q},\bm{\theta};-\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),
 \notag  & \qquad \qquad \qquad \qquad \qquad \qquad \qquad
 \forall q\in\mathcal{Q},\varkappa\in\mathcal{M}_{\mathrm S},\label{eq:P1-comm-F}
 & \varphi_{\mathrm{I},i,q,\varkappa}\geq\mu_{\mathrm{I},i,q,\varkappa}\big(-\mathbf{f}_{q},\bm{\theta};-\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),
 \notag  & \qquad \qquad \qquad \qquad \qquad \qquad \qquad
 \forall q\in\mathcal{Q},\varkappa\in\mathcal{M}_{\mathrm S},\label{eq:P1-comm-G}
 & \bar{\varphi}_{\mathrm{I},i,q,\varkappa}\geq\bar{\mu}_{\mathrm{I},i,q,\varkappa}\big( j\mathbf{f}_{q},\bm{\theta}; j\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),
  \notag  & \qquad \qquad \qquad \qquad \qquad \qquad \qquad
 \forall q\in\mathcal{Q},\varkappa\in\mathcal{M}_{\mathrm S}, \label{eq:P1-comm-H} 
 & \bar{\varphi}_{\mathrm{I},i,q,\varkappa}\geq\bar{\mu}_{\mathrm{I},i,q,\varkappa}\big(- j\mathbf{f}_{q},\bm{\theta};- j\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),
\notag  & \qquad \qquad \qquad \qquad \qquad \qquad \qquad
\forall q\in\mathcal{Q},\varkappa\in\mathcal{M}_{\mathrm S}.\label{eq:P1-comm-I}
\end{align}
\end{subequations}
\end{theorem}
\begin{IEEEproof}
Please see Appendix~\ref{sec:proof-comm-Convex}.
\end{IEEEproof}
Next, we observe that the harvested-power QoS thresholds at the $e$-th ER are typically several orders of magnitude smaller than the transmit power budget and interference terms. This disparity in magnitude can adversely affect the numerical conditioning of the resulting subproblems and lead to instability in off-the-shelf convex solvers. To improve numerical robustness while preserving equivalence, we reformulate the energy-harvesting constraints in~\eqref{eq:P1-EH} into a scaled, numerically better-conditioned form as follows:
\begin{align}
\frac{1}{\mathcal{P}_{e}}P_{\mathrm{E},e}(\mathbf{F},\bm{\theta})\geq1,\forall e\in\mathcal{E}.\label{eq:EH-normalized}
\end{align}
Since the LHS of~\eqref{eq:EH-normalized} is non-concave in the optimization variables $(\mathbf F, \bm \theta)$, we construct a locally tight concave minorant by invoking the following theorem, which yields a tractable inner approximation of the original constraint.
\begin{theorem}
\label{thm:EH-Convex}For a given $e\in\mathcal{E}$, a convex transformation of the constraints in~\eqref{eq:P1-EH} can be given by~\eqref{eq:P1-EH-CONVEX}, shown on the next page.  
\end{theorem}
\begin{IEEEproof}
Please see Appendix~\ref{sec:proof-EH-Convex}. 
\end{IEEEproof}
\begin{figure*}
	\begin{equation}
		\frac{\eta_{\mathrm{E},e}}{\mathcal{P}_{e}}\sum\nolimits_{q\in\mathcal{Q}}\Big[\psi_{\mathrm{E},e}\big(\mathbf{f}_{q},\bm{\theta};\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big)+\varsigma^{2}\Big(2\Re\big\{\big(\mathbf{f}_{q}^{(\upsilon)}\big)^{\mathsf{H}}\mathbf{f}_{q}\big\}
		-\|\mathbf{f}_{q}^{(\upsilon)}\|^{2}+\sum\nolimits_{\varkappa\in\mathcal{M}_{\mathrm S}}\widetilde{\psi}_{\mathrm{E},e,\varkappa}\big(\mathbf{f}_{q},\bm{\theta};\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big)\Big)\Big]\geq1.\label{eq:P1-EH-CONVEX}
	\end{equation}
\hrulefill 
\end{figure*}
We now turn our attention to the information leakage constraints in~\eqref{eq:P1-leakage}. Although the LHS of~\eqref{eq:P1-leakage} has the same functional form as that of~\eqref{eq:P1-comm}, the convexification strategy cannot mirror that in~\textbf{Theorem~\ref{thm:comm-Convex}} because the inequality direction in~\eqref{eq:P1-leakage} is reversed relative to~\eqref{eq:P1-comm}, and thus defines a different type of level set. Consequently, a distinct reformulation is required. The following theorem provides a convex representation that is equivalent to the original information leakage constraints in~\eqref{eq:P1-leakage}.
\begin{theorem}
\label{thm:leakage-Convex}For a given $e\in\mathcal{E}$ and $i\in\mathcal{I}$,
a convex reformulation of the constraints in~\eqref{eq:P1-leakage}
is given by 
\begin{subequations}
\label{eq:P1-leakage-CONVEX}
\begin{align}
 & \sigma_{\mathrm{E},e}^{2}+\sum \nolimits_{\jmath\in\mathcal{Q} \setminus \{i\}}\psi_{\mathrm{E},e}\big(\mathbf{f}_{\jmath},\bm{\theta};\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big)
 \nonumber 
 & +\varsigma^{2}\sum \limits_{q\in\mathcal{Q}}\Big[2\Re\big\{\big(\mathbf{f}_{q}^{(\upsilon)}\big)^{\mathsf{H}}\mathbf{f}_{q}\big\} + \sum\limits_{\varkappa\in\mathcal{M}_{\mathrm S}}\widetilde{\psi}_{\mathrm{E},e,\varkappa}\big(\mathbf{f}_{q},\bm{\theta};\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big)
 \nonumber  & 
\qquad \qquad \qquad -\|\mathbf{f}_{q}^{(\upsilon)}\|^{2}\Big] \geq \frac{1}{\Gamma_{\mathrm{E},e,i}}\big(\tau_{\mathrm{E},e,i}^{2}+\bar{\tau}_{\mathrm{E},e,i}^{2}\big),\label{eq:P1-leakage-a}

& \tau_{\mathrm{E},e,i}\geq\ \zeta_{\mathrm{E},e,i}\big(\mathbf{f}_{i},\bm{\theta};\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),\label{eq:P1-leakage-b}
& \tau_{\mathrm{E},e,i}\geq\ \zeta_{\mathrm{E},e,i}\big(-\mathbf{f}_{i},\bm{\theta};-\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),\label{eq:P1-leakage-c}
& \bar{\tau}_{\mathrm{E},e,i}\geq\ \bar{\zeta}_{\mathrm{E},e,i}\big( j\mathbf{f}_{i},\bm{\theta};- j\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big), \label{eq:P1-leakage-d} 
& \bar{\tau}_{\mathrm{E},e,i}\geq\ \bar{\zeta}_{\mathrm{E},e,i}\big(- j\mathbf{f}_{i},\bm{\theta};- j\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big).\label{eq:P1-leakage-e}
\end{align}
\end{subequations}
\end{theorem}
\begin{IEEEproof}
Please see Appendix~\ref{sec:proof-leakage-Convex}. 
\end{IEEEproof}
We now shift our focus to the sensing constraints in~\eqref{eq:P1-sensing}. These constraints are comparatively tractable because the receive combiners $\mathbf{c}_{l}$ are treated as fixed parameters. In this case, both the numerator and the denominator of the sensing SINR in~\eqref{eq:gamma_Bl} are convex functions of the transmit beamformers $\mathbf{F}$. Hence, for each target $l$, we construct a convex inner approximation of~\eqref{eq:P1-sensing} by linearizing the numerator around the current iterate $\mathbf{F}^{(\upsilon)}$ and performing suitable algebraic rearrangements of the resulting fractional inequality. This leads to the convex constraint in~\eqref{eq:gamma_Bl-Convex}, shown on the next page, where $\varpi_{lq}^{(\upsilon)}\triangleq\mathbf{c}_{l}^{\mathsf{H}}\widehat{\mathbf{V}}_{l}\mathbf{f}_{q}^{(\upsilon)}$.
\begin{figure*}
	\begin{multline} \label{eq:gamma_Bl-Convex}
		\frac{\bar{\alpha}}{\Gamma_{\mathrm{B},l}}\sum\nolimits_{q\in\mathcal{Q}}\Big[2\Re\big\{\big(\varpi_{lq}^{(\upsilon)}\big)^{\mathsf{H}}\mathbf{c}_{l}^{\mathsf{H}}\widehat{\mathbf{V}}_{l}\mathbf{f}_{q}\big\}-\big|\varpi_{lq}^{(\upsilon)}\big|^{2}\Big]  
		\geq\sum\nolimits_{q\in\mathcal{Q}}\Big(\bar{\alpha}\varsigma^{2}\big\Vert\mathbf{c}_{l}\big\Vert^{2}\big\Vert\mathbf{f}_{q}\big\Vert^{2}+\big|\mathbf{c}_{l}^{\mathsf{H}}\mathbf{G}\mathbf{f}_{q}\big|^{2}\Big) +\bar{\alpha}\sum\nolimits_{\jmath\in\mathcal{L} \setminus \{l\}}\sum\nolimits_{q\in\mathcal{Q}}\big|\mathbf{c}_{l}^{\mathsf{H}}\widehat{\mathbf{V}}_{\jmath}\mathbf{f}_{q}\big|^{2}+\sigma_{\mathrm{B}}^{2}\big|\big|\mathbf{c}_{l}^{\mathsf{H}}\big|\big|^{2}.
	\end{multline}
\hrulefill 
\end{figure*}
To prevent the increasing problem dimension induced by the introduction of multiple slack variables, we handle~\eqref{eq:P1-UMC} via a penalty-based convex relaxation. In particular, we first relax the equality constraints in~\eqref{eq:P1-UMC} to one-sided convex inequalities, thereby obtaining a convex outer approximation of the original feasible set, and then augment the objective in~\eqref{eq:P2} with an appropriately weighted exact-penalty term that measures the residual of these inequalities. For a sufficiently large penalty parameter, any optimal solution of the penalized problem satisfies the relaxed constraints with equality, thus recovering feasibility w.r.t.~\eqref{eq:P1-UMC}.
As a consequence,~\eqref{eq:P2}  can be rewritten as
\begin{subequations}
\label{eq:P3}
\begin{align}
\underset{\mathbf{F},\bm{\theta},\mathcal{S}}{\min}\  & \|\mathbf{F}\|_{\mathsf{F}}^{2}-\wp \big[ 2 \Re \big\{ \big(\bm{\theta}^{(\upsilon)}\big)^{\mathsf H} \bm{\theta}\big\} - \| \bm{\theta}^{(\upsilon)} \|^2 \big] \label{eq:P3-objective}
\text{s.t.}\  
 & \eqref{eq:P1-comm-CONVEX},\forall i\in\mathcal{I},\label{eq:P3-comm}
 & \eqref{eq:P1-EH-CONVEX},\forall e\in\mathcal{E},\label{eq:P3-EH}
 & \eqref{eq:P1-leakage-CONVEX},\forall e\in\mathcal{E},i\in\mathcal{I},\label{eq:P3-leakage}
 & \eqref{eq:gamma_Bl-Convex},\forall l\in\mathcal{L},\label{eq:P3-sensing}
 & \sum\nolimits_{\mathsf{m}\in\{\mathsf{R},\mathsf{T}\}}|\theta_{\mathsf{m},\varkappa}|^{2}\leq1,\forall\varkappa\in\mathcal{M}_{\mathrm S},\label{eq:P3-relaxed-UMC}
\end{align}
\end{subequations}
where $\wp\geq0$ is the regularization/penalty parameter and $\mathcal S$ is the set of auxiliary variables. 
Note that~\eqref{eq:P3} is an SOCP and can be efficiently handled by interior-point methods implemented in standard convex optimization packages, \emph{e.g.}, CVX or CVXPY, together with state-of-the-art conic solvers such as MOSEK. The resulting AO-based procedure for jointly optimizing $\mathbf{F}$, $\bm{\theta}$, and $\mathbf{C}$ is summarized in \textbf{Algorithm~\ref{algo}}.
\begin{algorithm}[t]
\caption{The Proposed AO-based Algorithm to Solve~\eqref{eq:P1}}
\label{algo}
\KwIn{$\mathbf{F}^{(0)}$, $\bm{\theta}^{(0)}$}
$\upsilon\leftarrow 0$\;
\Repeat{convergence }{
Given $\mathbf{F}^{(\upsilon)}$ and $\bm{\theta}^{(\upsilon)}$, obtain $\mathbf{C}^{(\upsilon+1)}$ via~\eqref{eq:cl_opt}\;
Given $\mathbf{C}^{(\upsilon+1)}$, solve~\eqref{eq:P3} to obtain $\mathbf{F}^{(\upsilon+1)}$,
$\bm{\theta}^{(\upsilon+1)}$\;
$\upsilon\leftarrow\upsilon+1$\;
}
$\mathbf{F}_{\mathrm{opt}}\leftarrow\mathbf{F}^{(\upsilon)}$, $\bm{\theta}_{\mathrm{opt}}\leftarrow\bm{\theta}^{(\upsilon)}$,
$\mathbf{C}_{\mathrm{opt}}\leftarrow\mathbf{C}^{(\upsilon)}$\;
\KwOut{$\mathbf{F}_{\mathrm{opt}}$, $\bm{\theta}_{\mathrm{opt}}$,
$\mathbf{C}_{\mathrm{opt}}$}
\end{algorithm}
\subsection{Convergence Analysis}
Note that the optimal receive beamforming matrix $\mathbf{C}$ is obtained via the \emph{generalized Rayleigh quotient maximization} method, and therefore the convergence behavior of the proposed AO-based algorithm in \textbf{Algorithm~\ref{algo}} is essentially determined by the convergence of subproblem~\eqref{eq:P3}. To facilitate analysis, we define the objective function of~\eqref{eq:P3} prior to linearizing the regularization term as $f(\mathbf{F},\bm{\theta})\triangleq \|\mathbf{F}\|_{\mathsf{F}}^{2}-\wp\| \bm{\theta} \|^2$. At the $\upsilon$-th iteration, let $f(\mathbf{F}^{(\upsilon)},\bm{\theta}^{(\upsilon)})$ denotes the optimal solution of~\eqref{eq:P3}. 
Since this solution remains feasible for the subsequent iteration, the sequence of objective values satisfies $f(\mathbf{F}^{(\upsilon+1)},\bm{\theta}^{(\upsilon+1)})  \leq f(\mathbf{F}^{(\upsilon)},\bm{\theta}^{(\upsilon)})$, which implies that the sequence $\{f(\mathbf{F}^{(\upsilon)},\bm{\theta}^{(\upsilon)})\}$ is monotonically non-increasing.
In addition, the non-negativity of $\|\mathbf{F}\|_{\mathsf{F}}^{2}$ together with the boundedness of $\| \bm{\theta} \|^2$ enforced by the power cone in~\eqref{eq:P3-relaxed-UMC} ensures that $f(\mathbf{F},\bm{\theta}) \geq - \wp M_\mathrm S$. Therefore, $\{f(\mathbf{F}^{(\upsilon)},\bm{\theta}^{(\upsilon)})\}$ is bounded from below and convergent by the monotone convergence theorem.
As for the convergence of the iterates, the AO framework guarantees that the sequence admits limit points, and any such limit point satisfies the first-order stationarity condition. Therefore, \textbf{Algorithm~\ref{algo}} is guaranteed to produce a convergent sequence of objective values, and all its limit points are stationary solutions of the original problem.
\subsection{Complexity Analysis}
We now analyze the computational complexity of \textbf{Algorithm~\ref{algo}}. 
The complexity of each iteration is primarily dominated by the operations in lines 3 and 4 of the algorithm.
Specifically, the calculation of the
optimal $\mathbf{C}$ involves matrix multiplication, matrix inversion, and eigenvalue decomposition presented in~\eqref{eq:gamma_Bl_transform}, with a complexity of $\mathcal{O}(L(M_{\mathrm{R}}^3 + M_{\mathrm{T}}^2 M_{\mathrm{R}} + M_{\mathrm{T}} M_{\mathrm{R}}^2))$.
Subsequently, for line 4, the total number of real-valued optimization variables in~\eqref{eq:P3} is $2[M_{\mathrm{T}}Q+2M_{\mathrm S}+2I(Q-1)+2IQM_{\mathrm S}+2EI] + 1$ and the total number of conic constraints of second order is $I+4I(Q-1)+4IQM_{\mathrm S}+E+5EI+L+M_{\mathrm S}+1$. 
Therefore, following~\cite[Sec.~6.6.2]{11-BenTal-Convex-Opt}, the per-iteration complexity for~\eqref{eq:P3} in line 4 is given by $\mathcal{O}((IQM_{\mathrm S}+EI)^{0.5} (IQM_{\mathrm S}+EI+M_{\mathrm{T}}Q) (I^2Q^2M_{\mathrm S}^2 + IQM_{\mathrm S} M_{\mathrm{T}}^2 + E^2I^2 + M_{\mathrm{T}}^2Q^2I + EIM_{\mathrm{T}}^2 + LM_{\mathrm{T}}^2Q^2 ) )$.
Since, in a practical setting, $M_{\mathrm S} \gg \max\{M_{\mathrm{T}}, M_{\mathrm{R}}, I, E, L, Q\}$, the overall complexity of each iteration for \textbf{Algorithm~\ref{algo}} can be approximated by $\mathcal{O}(M_{\mathrm S}^{3.5})$.
