\tau_{\mathrm{I},i,\jmath}& \geq 0.25 \Big[\big\Vert\widehat{\mathbf{z}}_{\mathrm{I},i}^{\mathsf{H}}-\mathbf{f}_{\jmath}\big\Vert^{2}+\big\Vert\big(\widehat{\mathbf{z}}_{\mathrm{I},i}^{(\upsilon)}\big)^{\mathsf{H}}+\mathbf{f}_{\jmath}^{(\upsilon)}\big\Vert^{2}
\nonumber  & \qquad\qquad\qquad 
-2\Re\big\{\big[\widehat{\mathbf{z}}_{\mathrm{I},i}^{(\upsilon)}+\big(\mathbf{f}_{\jmath}^{(\upsilon)}\big)^{\mathsf{H}}\big]\big(\widehat{\mathbf{z}}_{\mathrm{I},i}^{\mathsf{H}}+\mathbf{f}_{\jmath}\big)\big\}\Big]
\nonumber  &
\triangleq\zeta_{\mathrm{I},i,\jmath}\big(-\mathbf{f}_{\jmath},\bm{\theta};-\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big).\label{eq:A-5-2}
\end{align}
\end{subequations}
Following a similar line of arguments, one can convexify~\eqref{eq:A-3-3}–\eqref{eq:A-3-5}, for fixed $j \in \mathcal Q \setminus \{i\}$, $q \in \mathcal Q$, and $\varkappa \in \mathcal M_{\mathrm S}$
as follows: 
\begin{subequations}
	\label{eq:A-7}
	\begin{align}
		\bar{\tau}_{\mathrm{I},i,\jmath} \geq & \ \bar{\zeta}_{\mathrm{I},i,\jmath} \big(  j\mathbf{f}_{\jmath},\bm{\theta};  j\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big), 
		\bar{\tau}_{\mathrm{I},i,\jmath} \geq & \ \bar{\zeta}_{\mathrm{I},i,\jmath} \big( - j\mathbf{f}_{\jmath},\bm{\theta};  -j\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big), 
		\varphi_{\mathrm I, i, q, \varkappa} \geq & \ \mu_{\mathrm{I},i,q,\varkappa} \big(\mathbf{f}_{q},\bm{\theta}; \mathbf{f}_{q}^{(\upsilon)}\!,\bm{\theta}^{(\upsilon)} \big), 
		\varphi_{\mathrm I, i, q, \varkappa} \geq & \ \mu_{\mathrm{I},i,q,\varkappa} \big(-\mathbf{f}_{q},\bm{\theta};-\mathbf{f}_{q}^{(\upsilon)}\!,\bm{\theta}^{(\upsilon)} \big), 
		\bar{\varphi}_{\mathrm I, i, q, \varkappa} \geq & \ \bar{\mu}_{\mathrm{I},i,q,\varkappa} \big(\mathbf{f}_{q},\bm{\theta}; \mathbf{f}_{q}^{(\upsilon)}\!,\bm{\theta}^{(\upsilon)} \big), 
		\bar{\varphi}_{\mathrm I, i, q, \varkappa} \geq & \ \bar{\mu}_{\mathrm{I},i,q,\varkappa} \big(-\mathbf{f}_{q},\bm{\theta};-\mathbf{f}_{q}^{(\upsilon)}\!,\bm{\theta}^{(\upsilon)} \big),
	\end{align}
\end{subequations}
where $\bar{\zeta}_{\mathrm{I},i,\jmath} \big(  j\mathbf{f}_{\jmath},\bm{\theta};  j\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big) = 0.25\Big[\big\Vert\widehat{\mathbf{z}}_{\mathrm{I},i}^{\mathsf{H}}- j\mathbf{f}_{\jmath}\big\Vert^{2}+\big\Vert\big(\widehat{\mathbf{z}}_{\mathrm{I},i}^{(\upsilon)}\big)^{\mathsf{H}}+ j\mathbf{f}_{\jmath}^{(\upsilon)}\big\Vert^{2}
-2\Re\big\{\big[\widehat{\mathbf{z}}_{\mathrm{I},i}^{(\upsilon)}- j\big(\mathbf{f}_{\jmath}^{(\upsilon)}\big)^{\mathsf{H}}\big]\big(\widehat{\mathbf{z}}_{\mathrm{I},i}^{\mathsf{H}}+ j\mathbf{f}_{\jmath}\big)\big\}\Big]$, 
$\bar{\zeta}_{\mathrm{I},i,\jmath} \big( - j\mathbf{f}_{\jmath},\bm{\theta};  -j\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big) =  0.25 \Big[\big\Vert\widehat{\mathbf{z}}_{\mathrm{I},i}^{\mathsf{H}}+ j\mathbf{f}_{\jmath}\big\Vert^{2}+\big\Vert\big(\widehat{\mathbf{z}}_{\mathrm{I},i}^{(\upsilon)}\big)^{\mathsf{H}}- j\mathbf{f}_{\jmath}^{(\upsilon)}\big\Vert^{2}-2\Re\big\{\big[\widehat{\mathbf{z}}_{\mathrm{I},i}^{(\upsilon)}+ j\big(\mathbf{f}_{\jmath}^{(\upsilon)}\big)^{\mathsf{H}}\big]\big(\widehat{\mathbf{z}}_{\mathrm{I},i}^{\mathsf{H}}- j\mathbf{f}_{\jmath}\big)\big\}\Big]$, 
$\mu_{\mathrm{I},i,q,\varkappa} \big(\mathbf{f}_{q},\bm{\theta}; \mathbf{f}_{q}^{(\upsilon)}\!,\bm{\theta}^{(\upsilon)} \big) = 0.25\Big[\big\Vert(\theta_{\mathrm{I},i,\varkappa}\mathbf{h}_{\varkappa})^{\mathsf{H}}+\mathbf{f}_{q}\big\Vert^{2}+\big\Vert(\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa})^{\mathsf{H}}-\mathbf{f}_{q}^{(\upsilon)}\big\Vert^{2}-2\Re\big\{\big[\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa}-\big(\mathbf{f}_{q}^{(\upsilon)}\big)^{\mathsf{H}}\big]\big[(\theta_{\mathrm{I},i,\varkappa}\mathbf{h}_{\varkappa})^{\mathsf{H}}-\mathbf{f}_{q}\big]\big\}\Big]$,
$\mu_{\mathrm{I},i,q,\varkappa} \big(-\mathbf{f}_{q},\bm{\theta};-\mathbf{f}_{q}^{(\upsilon)}\!,\bm{\theta}^{(\upsilon)} \big) = 0.25\Big[\big\Vert(\theta_{\mathrm{I},i,\varkappa}\mathbf{h}_{\varkappa})^{\mathsf{H}}-\mathbf{f}_{q}\big\Vert^{2}+\big\Vert(\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa})^{\mathsf{H}}+\mathbf{f}_{q}^{(\upsilon)}\big\Vert^{2}-2\Re\big\{\big[\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa}+\big(\mathbf{f}_{q}^{(\upsilon)}\big)^{\mathsf{H}}\big]\big[(\theta_{\mathrm{I},i,\varkappa}\mathbf{h}_{\varkappa})^{\mathsf{H}}+\mathbf{f}_{q}\big]\big\}\Big]$,
$\bar{\mu}_{\mathrm{I},i,q,\varkappa} \big(\mathbf{f}_{q},\bm{\theta}; \mathbf{f}_{q}^{(\upsilon)}\!,\bm{\theta}^{(\upsilon)} \big) = 0.25\big[\big\Vert(\theta_{\mathrm{I},i,\varkappa}\mathbf{h}_{\varkappa})^{\mathsf{H}}- j\mathbf{f}_{q}\big\Vert^{2}+\big\Vert(\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa})^{\mathsf{H}}+ j\mathbf{f}_{q}^{(\upsilon)}\big\Vert^{2} -2\Re\big\{\big[\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa}\!-\!j\big(\mathbf{f}_{q}^{(\upsilon)}\big)^{\mathsf{H}}\big]\big[(\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa})^{\mathsf{H}}+ j\mathbf{f}_{q}\big]\big\}\Big]$, and 
$\bar{\mu}_{\mathrm{I},i,q,\varkappa} \big(-\mathbf{f}_{q},\bm{\theta};-\mathbf{f}_{q}^{(\upsilon)}\!,\bm{\theta}^{(\upsilon)} \big) = 0.25\Big[\big\Vert(\theta_{\mathrm{I},i,\varkappa}\mathbf{h}_{\varkappa})^{\mathsf{H}}+ j\mathbf{f}_{q}\big\Vert^{2}+\big\Vert(\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa})^{\mathsf{H}}- j\mathbf{f}_{q}^{(\upsilon)}\big\Vert^{2}
-2\Re\big\{\big[\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa}+ j\big(\mathbf{f}_{q}^{(\upsilon)}\big)^{\mathsf{H}}\big]\big[(\theta_{\mathrm{I},i,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa})^{\mathsf{H}} \! - \! j\mathbf{f}_{q}\big]\big\}\Big]$.
It can be verified that the right-hand sides of~\eqref{eq:A-5} and~\eqref{eq:A-7} are jointly convex in $(\mathbf{F},\bm{\theta})$. Hence, by collecting the constraints in~\eqref{eq:A-3-1}, \eqref{eq:A-5}, and~\eqref{eq:A-7}, we obtain an equivalent convex reformulation of the original constraints in~\eqref{eq:P1-comm}, as stated in~\eqref{eq:P1-comm-CONVEX}, which concludes the proof.
\section{\label{sec:proof-EH-Convex}Proof of Theorem~\ref{thm:EH-Convex}}
Using~\eqref{eq:harvested_power_Ee} and~\eqref{eq:EH-normalized},
for a given $e\in\mathcal{E}$, we write 
\begin{multline}
\frac{\eta_{\mathrm{E},e}}{\mathcal{P}_{e}}\sum\nolimits_{q\in\mathcal{Q}}\Big[|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{q}|^{2}+\varsigma^{2}\Big(\big\Vert\mathbf{f}_{q}\big\Vert^{2}
+\sum\nolimits_{\varkappa\in\mathcal{M}_{\mathrm S}}|\theta_{\mathrm{E},e,\varkappa}\mathbf{h}_{\varkappa}\mathbf{f}_{q}|^{2}\Big)\Big]\geq1.\label{eq:B-1}
\end{multline}
Following the same reasoning as in~\eqref{eq:A-2}, we construct a concave minorant of the term $\big|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{q}\big|^{2}$, which is jointly concave in $(\mathbf{F},\bm{\theta})$, and can be written as 
\begin{align}
|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{q}|^{2}&\geq
\Re\Big\{\big(\mathbf{b}_{\mathrm{E},e}^{(\upsilon)}\big)^{\mathsf{H}}\big[a_{\mathrm{E},e}^{(\upsilon)}\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}+\mathbf{f}_{q}\big]\Big\}- \frac{1}{2}\big\Vert\mathbf{b}_{\mathrm{E},e}^{(\upsilon)}\big\Vert^{2}
\nonumber  & \qquad \qquad \qquad \qquad
- \frac{1}{2}\big\Vert a_{\mathrm{E},e}^{(\upsilon)}\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}-\mathbf{f}_{q}\big\Vert^{2}-\big|a_{\mathrm{E},e}^{(\upsilon)}\big|^{2}
\nonumber  &
\triangleq
\psi_{\mathrm{E},e}\big(\mathbf{f}_{q},\bm{\theta};\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),\label{eq:B-2}
\end{align}
where 
$a_{\mathrm{E},e}^{(\upsilon)}\triangleq\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}\mathbf{f}_{q}^{(\upsilon)}$
and $\mathbf{b}_{\mathrm{E},e}^{(\upsilon)}\triangleq a_{\mathrm{E},e}^{(\upsilon)}\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}\big)^{\mathsf{H}}+\mathbf{f}_{q}^{(\upsilon)}$.
Next, a first-order Taylor approximation of $\big\Vert\mathbf{f}_{q}\big\Vert^{2}$
can be given as 
\begin{align}
\big\Vert\mathbf{f}_{q}\big\Vert^{2}\geq2\Re\big\{\big(\mathbf{f}_{q}^{(\upsilon)}\big)^{\mathsf{H}}\mathbf{f}_{q}\big\}-\|\mathbf{f}_{q}^{(\upsilon)}\|^{2}.\label{eq:B-3}
\end{align}
At the end, similar to~\eqref{eq:A-2}, a concave lower bound on
the term $|\theta_{\mathrm{E},e,\varkappa}\mathbf{h}_{\varkappa}\mathbf{f}_{q}|^{2}$
can be given by 
\begin{align}
& |\theta_{\mathrm{E},e,\varkappa}\mathbf{h}_{\varkappa}\mathbf{f}_{q}|^{2} \nonumber 
\geq & \ 
\Re\Big\{\big(\widetilde{\mathbf{b}}_{\mathrm{E},e,q,\varkappa}^{(\upsilon)}\big)^{\mathsf{H}}\big[\widetilde{a}_{\mathrm{E},e,q,\varkappa}^{(\upsilon)}(\theta_{\mathrm{E},e,\varkappa}\mathbf{h}_{\varkappa})^{\mathsf{H}}+\mathbf{f}_{q}\big]\Big\} -\|\widetilde{a}_{\mathrm{E},e,q,\varkappa}^{(\upsilon)}\|^{2}
\nonumber  
& \qquad
- 0.5\big\Vert\widetilde{a}_{\mathrm{E},e,q,\varkappa}^{(\upsilon)}(\theta_{\mathrm{E},e,\varkappa}\mathbf{h}_{\varkappa})^{\mathsf{H}}-\mathbf{f}_{q}\big\Vert^{2}
- 0.5\big\Vert\widetilde{\mathbf{b}}_{\mathrm{E},e,q,\varkappa}^{(\upsilon)}\big\Vert^{2}
\nonumber  &
\triangleq
\widetilde{\psi}_{\mathrm{E},e,\varkappa}\big(\mathbf{f}_{q},\bm{\theta};\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),\label{eq:B-4}
\end{align}
where 
$\widetilde{a}_{\mathrm{E},e,q,\varkappa}^{(\upsilon)}\triangleq(\theta_{\mathrm{E},e,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa})\mathbf{f}_{q}^{(\upsilon)}$
and $\widetilde{\mathbf{b}}_{\mathrm{E},e,q,\varkappa}^{(\upsilon)}\triangleq\widetilde{a}_{\mathrm{E},e,q,\varkappa}^{(\upsilon)}(\theta_{\mathrm{E},e,\varkappa}^{(\upsilon)}\mathbf{h}_{\varkappa})^{\mathsf{H}}+\mathbf{f}_{q}^{(\upsilon)}$.
By aggregating~\eqref{eq:B-1}–\eqref{eq:B-4}, we obtain the convex representation of the energy-harvesting constraints in~\eqref{eq:P1-EH}, as given in~\eqref{eq:P1-EH-CONVEX}, which completes the proof. 
\section{\label{sec:proof-leakage-Convex}Proof of Theorem~\ref{thm:leakage-Convex}}
Using~\eqref{eq:gamma_Ee} and~\eqref{eq:P1-leakage}, for a given
$e\in\mathcal{E}$ and $i\in\mathcal{I}$, one can write
\begin{multline}
\sigma_{\mathrm{E},e}^{2}+\sum\nolimits_{\jmath\in\mathcal{Q} \setminus \{i\}}\big|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{\jmath}\big|^{2}
+\varsigma^{2}\sum\limits_{q\in\mathcal{Q}}\Big(\big\Vert\mathbf{f}_{q}\big\Vert^{2}+\big\Vert\bm{\Theta}_{\mathrm{E},e}\mathbf{H}\mathbf{f}_{q}\big\Vert^{2}\Big)\geq\frac{1}{\Gamma_{\mathrm{E},e,i}}|\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{i}|^{2}.\label{eq:C-1}
\end{multline}
Since the preceding inequality defines a nonconvex constraint (neither side is convex or concave in the optimization variables), we construct a concave minorant for the left-hand side and a convex majorant for the right-hand side. In particular, by following the surrogate construction in Appendices~\ref{sec:proof-comm-Convex} and~\ref{sec:proof-EH-Convex}, we obtain the following tractable approximations: 
\begin{subequations}
\label{eq:C-3}
\begin{align}
 & \sigma_{\mathrm{E},e}^{2}+\sum \nolimits_{\jmath\in\mathcal{Q} \setminus \{i\}}\psi_{\mathrm{E},e}\big(\mathbf{f}_{\jmath},\bm{\theta};\mathbf{f}_{\jmath}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big)
\nonumber 
& +\varsigma^{2}\sum \limits_{q\in\mathcal{Q}}\Big[2\Re\big\{\big(\mathbf{f}_{q}^{(\upsilon)}\big)^{\mathsf{H}}\mathbf{f}_{q}\big\} + \sum\limits_{\varkappa\in\mathcal{M}_{\mathrm S}}\widetilde{\psi}_{\mathrm{E},e,\varkappa}\big(\mathbf{f}_{q},\bm{\theta};\mathbf{f}_{q}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big)
\nonumber  & 
\qquad \qquad \qquad  -\|\mathbf{f}_{q}^{(\upsilon)}\|^{2}\Big] \geq \frac{1}{\Gamma_{\mathrm{E},e,i}}\big(\tau_{\mathrm{E},e,i}^{2}+\bar{\tau}_{\mathrm{E},e,i}^{2}\big),\label{eq:C-3a}
 & \tau_{\mathrm{E},e,i}\geq|\Re\{\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{i}\}|,\label{eq:C-3b}
 & \bar{\tau}_{\mathrm{E},e,i}\geq|\Im\{\widehat{\mathbf{z}}_{\mathrm{E},e}\mathbf{f}_{i}\}|,\label{eq:C-3c}
\end{align}
\end{subequations}
where $\psi_{\mathrm{E},e}(\cdot,\cdot;\cdot,\cdot)$ and $\widetilde{\psi}_{\mathrm{E},e}(\cdot,\cdot;\cdot,\cdot)$ are defined in Appendix~\ref{sec:proof-EH-Convex}, and $\tau_{\mathrm{E},e,i}$ and $\bar{\tau}_{\mathrm{E},e,i}$ are auxiliary slack variables. By construction, the LHS of~\eqref{eq:C-3a} is jointly concave in $(\mathbf{F},\bm{\theta})$, and the RHS is convex, so~\eqref{eq:C-3a} already defines a convex constraint. In contrast, the right-hand sides of~\eqref{eq:C-3b} and~\eqref{eq:C-3c} remain nonconvex due to the bilinear coupling between $\mathbf{F}$ and $\bm{\theta}$. To embed these constraints into the SCA framework, we construct locally tight convex majorants for the nonconvex terms, following the same surrogate-design principles as in Appendix~\ref{sec:proof-comm-Convex}, which yields
\begin{subequations}
	\label{eq:C-4}
	\begin{align}
		\tau_{\mathrm{E},e,i} & \geq \zeta_{\mathrm{E},e,i}\big(\mathbf{f}_{i},\bm{\theta};\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big), 
		\tau_{\mathrm{E},e,i} & \geq \zeta_{\mathrm{E},e,i}\big(-\mathbf{f}_{i},\bm{\theta};-\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big), 
		\bar{\tau}_{\mathrm{E},e,i} & \geq \bar{\zeta}_{\mathrm{E},e,i}\big( j\mathbf{f}_{i},\bm{\theta}; j\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big), 
		\bar{\tau}_{\mathrm{E},e,i} & \geq \bar{\zeta}_{\mathrm{E},e,i}\big( -j\mathbf{f}_{i},\bm{\theta}; -j\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big),
	\end{align}
\end{subequations}
where $\zeta_{\mathrm{E},e,i}\big(\mathbf{f}_{i},\bm{\theta};\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big) = 0.25\Big[\big\Vert\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}+\mathbf{f}_{i}\big\Vert^{2}+\big\Vert\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}\big)^{\mathsf{H}}+\mathbf{f}_{i}^{(\upsilon)}\big\Vert^{2}
-2\Re\big\{\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}-\big(\mathbf{f}_{i}^{(\upsilon)}\big)^{\mathsf{H}}\big)\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}-\mathbf{f}_{i}\big)\big\}\Big]$, 
$\zeta_{\mathrm{E},e,i}\big(-\mathbf{f}_{i},\bm{\theta};-\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big) = 0.25\Big[\big\Vert\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}-\mathbf{f}_{i}\big\Vert^{2}+\big\Vert\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}\big)^{\mathsf{H}}-\mathbf{f}_{i}^{(\upsilon)}\big\Vert^{2}
-2\Re\big\{\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}+\big(\mathbf{f}_{i}^{(\upsilon)}\big)^{\mathsf{H}}\big)\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}+\mathbf{f}_{i}\big)\big\}\Big]$, 
$\bar{\zeta}_{\mathrm{E},e,i}\big( j\mathbf{f}_{i},\bm{\theta}; j\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big) = 0.25\Big[\big\Vert\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}- j\mathbf{f}_{i}\big\Vert^{2}+\big\Vert\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}\big)^{\mathsf{H}}+ j\mathbf{f}_{i}^{(\upsilon)}\big\Vert^{2}
-2\Re\big\{\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}-\big( j\mathbf{f}_{i}^{(\upsilon)}\big)^{\mathsf{H}}\big)\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}+ j\mathbf{f}_{i}\big)\big\}\Big]$, and 
$\bar{\zeta}_{\mathrm{E},e,i}\big( -j\mathbf{f}_{i},\bm{\theta}; -j\mathbf{f}_{i}^{(\upsilon)},\bm{\theta}^{(\upsilon)}\big) = 0.25\Big[\big\Vert\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}+ j\mathbf{f}_{i}\big\Vert^{2}+\big\Vert\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}\big)^{\mathsf{H}}- j\mathbf{f}_{i}^{(\upsilon)}\big\Vert^{2}
-2\Re\big\{\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{(\upsilon)}+\big( j\mathbf{f}_{i}^{(\upsilon)}\big)^{\mathsf{H}}\big)\big(\widehat{\mathbf{z}}_{\mathrm{E},e}^{\mathsf{H}}- j\mathbf{f}_{i}\big)\big\}\Big]$.
Using~\eqref{eq:C-3a} and \eqref{eq:C-4}, convex reformulation of the constraints in~\eqref{eq:P1-leakage} is given by~\eqref{eq:P1-leakage-CONVEX}. The proof is completed.
