where $\bar{\mH}_k$, $\tilde{\mH}$, and $ \tilde{\mH}_k$ are defined in Lemma \ref{lem:1}.
Using \eqref{eq:sef}, the gradient of $\mathsf{SE}_k$ with respect to $\mF$ is obtained as \cite{hjorungnes2011complex}
\begin{align}
 \nabla_{\mF} \mathsf{SE}_k &=  \frac{\partial }{\partial \mF^*}\log_2\left(\tr{\mF \mFh\bar{\mH}_k}+ \hat{\sigma}_k^2 \right) \nonumber&- \frac{\partial }{\partial \mF^*}\log_2\left(\tr{\mF_{\bar{k}}\mF_{\bar{k}}^{\mathsf{H}}\bar{\mH}_k}+ \hat{\sigma}_k^2 \right)\nonumber&= 2\frac{\bar{\mH}_k\mF}{\ln2\left(\tr{\mF \mFh \bar{\mH}_k}+ \hat{\sigma}_k^2\right)}\nonumber&-2\frac{\bar{\mH}_k\mF_{\bar{k}}}{\ln2\left(\tr{\mF_{\bar{k}}\mF_{\bar{k}}^{\mathsf{H}} \bar{\mH}_k}+ \hat{\sigma}_k^2\right)}.
 \label{gradsekf}
\end{align}
Similarly, using \eqref{eq:segamma}, the gradient of $\mathsf{SE}_k$ with respect to $\bPhi$ is given by
\begin{align}
 \nabla_{\bPhi} \mathsf{SE}_k &=  \frac{\partial }{\partial \bPhi^*}\log_2\left(\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG}+ \sigma_k^2\right) \nonumber&- \frac{\partial }{\partial \bPhi^*}\log_2\left(\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG_k}+ \sigma_k^2\right)\nonumber&=2\frac{\mT_k\bPhi \mG}{\ln2\left(\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG }+ \sigma_k^2\right)}\circ \mI_N\nonumber&-2\frac{\mT_k\bPhi \mG_k}{\ln2\left(\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG_k}+ \sigma_k^2\right)}\circ \mI_N.
 \label{gradsekgamma}
\end{align}
Consequently, the gradients of $\mathsf{SE}$ with respect to $\mF$ and $\bPhi$ are given, respectively, by
\begin{align}
 \nabla_{\mF} \mathsf{SE} = \sum_{k=1}^K \nabla_{\mF} \mathsf{SE}_k,
 \label{gradsef}

 \nabla_{\bPhi} \mathsf{SE} = \sum_{k=1}^K \nabla_{\bPhi} \mathsf{SE}_k.
 \label{gradsegamma}
\end{align}
The gradient of $P_{\mathsf{tot}}$, based on \eqref{eq:powertot}, is given by
\begin{align}
 \nabla_{\mF} P_{\mathsf{tot}} &=\frac{1}{\xi}\mF+\frac{1}{\zeta}\mHt^{\mathsf{H}}\bPhi^{\mathsf{H}}\bPhi\mHt\mF,
 \label{eq:ptotgradf}
 \nabla_{\bPhi} P_{\mathsf{tot}} &= \frac{1}{\zeta}\Big(\bPhi (\tilde{\mH} + \sigma_{\mathsf{R}}^2\mI)\Big)\circ \mI_N= \frac{1}{\zeta}\bPhi \mG\circ \mI_N.
 \label{eq:ptotgradgamma}
\end{align}
Finally, substituting \eqref{gradsef} and \eqref{eq:ptotgradf} into \eqref{eq:chainf} yields \eqref{eq:gradf}. Similarly, substituting \eqref{gradsegamma} and \eqref{eq:ptotgradgamma} into \eqref{eq:chaingamma} gives \eqref{eq:gradgamma}, which completes the proof of Lemma \ref{lem:1}.
